[{"order":1,"type":"heading","text":"Secure Storage, Biometric Authentication, and Root Detection in Android (Kotlin)"},{"order":2,"type":"paragraph","text":"Building a secure Android application requires protecting sensitive data at rest, enforcing strong authentication mechanisms, and ensuring the environment hasn't been compromised. This tutorial covers three critical pillars of Android security: EncryptedSharedPreferences for secure storage, BiometricPrompt for user authentication, and root detection techniques."},{"order":3,"type":"subheading","text":"1. Secure Storage with EncryptedSharedPreferences"},{"order":4,"type":"paragraph","text":"Standard SharedPreferences stores data in plain XML files, making it vulnerable on rooted devices. EncryptedSharedPreferences wraps SharedPreferences and automatically encrypts keys and values using Android Keystore."},{"order":5,"type":"code","text":"import android.content.Context
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey

fun getSecurePreferences(context: Context):
        android.content.SharedPreferences {
    val masterKey = MasterKey.Builder(context)
        .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
        .build()

    return EncryptedSharedPreferences.create(
        context,
        "secure_prefs",
        masterKey,
        EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_GCM,
        EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
    )
}"},{"order":6,"type":"subheading","text":"2. Biometric Authentication"},{"order":7,"type":"paragraph","text":"The BiometricPrompt API allows you to integrate fingerprint and face recognition seamlessly. First, ensure you include the androidx.biometric dependency in your build.gradle file."},{"order":8,"type":"code","text":"import androidx.biometric.BiometricPrompt
import androidx.core.content.ContextCompat
import androidx.fragment.app.FragmentActivity

fun showBiometricPrompt(
    activity: FragmentActivity,
    onSuccess: () -> Unit,
    onError: (String) -> Unit
) {
    val executor = ContextCompat.getMainExecutor(activity)
    val biometricPrompt = BiometricPrompt(activity,
        executor,
        object : BiometricPrompt.AuthenticationCallback() {
            override fun onAuthenticationSucceeded(
                result: BiometricPrompt.AuthenticationResult
            ) {
                super.onAuthenticationSucceeded(result)
                onSuccess()
            }

            override fun onAuthenticationError(
                errorCode: Int,
                errString: CharSequence
            ) {
                super.onAuthenticationError(errorCode, errString)
                onError(errString.toString())
            }
        })

    val promptInfo = BiometricPrompt.PromptInfo.Builder()
        .setTitle("Authenticate to proceed")
        .setSubtitle("Use your biometric credential")
        .setNegativeButtonText("Cancel")
        .build()

    biometricPrompt.authenticate(promptInfo)
}"},{"order":9,"type":"subheading","text":"3. Root Detection"},{"order":10,"type":"paragraph","text":"Detecting if a device is rooted helps prevent running your app in an insecure environment. Common indicators include the presence of Superuser APKs, busybox binaries, and test-keys in the build tags."},{"order":11,"type":"code","text":"import android.os.Build
import java.io.File

object RootChecker {

    fun isDeviceRooted(): Boolean {
        return checkBuildTags() || checkRootBinaries() || checkSuperUserApk()
    }

    private fun checkBuildTags(): Boolean {
        val buildTags = android.os.Build.TAGS
        return buildTags != null && buildTags.contains("test-keys")
    }

    private fun checkRootBinaries(): Boolean {
        val paths = arrayOf(
            "/system/app/Superuser.apk",
            "/sbin/su",
            "/system/bin/su",
            "/system/xbin/su",
            "/data/local/xbin/su",
            "/data/local/bin/su",
            "/system/sd/xbin/su",
            "/system/bin/failsafe/su",
            "/data/local/su"
        }
        for (path in paths) {
            if (File(path).exists()) return true
        }
        return false
    }

    private fun checkSuperUserApk(): Boolean {
        val paths = arrayOf(
            "/system/app/Superuser.apk",
            "/system/app/SuperSU.apk"
        )
        for (path in paths) {
            if (File(path).exists()) return true
        }
        return false
    }
}"},{"order":12,"type":"subheading","text":"Best Practices"},{"order":13,"type":"bullet_point","text":"Always combine EncryptedSharedPreferences with ProGuard or R8 code shrinking to protect your reverse-engineering attack surface."},{"order":14,"type":"bullet_point","text":"Never rely solely on client-side root detection. Implement server-side attestation (such as Play Integrity API) for high-security applications."},{"order":15,"type":"bullet_point","text":"Handle biometric fallback scenarios gracefully by allowing users to enter a secure device PIN or application password."}]
